using System;
using System.IO;
using UnityEditor;
using UnityEngine;
namespace HotelTogether.Editor {
 public static class HotelCashBuilder {
  [MenuItem("Hotel Together/Economy/Build supplied cash")]
  public static void Build(){const string art="Assets/HotelTogether/Art/Cash/";const string output="Assets/HotelTogether/Resources/HotelTogetherCash/";Directory.CreateDirectory(output);AssetDatabase.Refresh();var source=AssetDatabase.LoadAssetAtPath<GameObject>(art+"cash_lowpoly.glb");if(!source)throw new InvalidOperationException("Cash model has not imported.");Mesh original=null;foreach(var filter in source.GetComponentsInChildren<MeshFilter>(true))if(filter.name.StartsWith("C2_",StringComparison.Ordinal)){original=filter.sharedMesh;break;}if(!original)throw new InvalidOperationException("Source cash bundle mesh missing.");var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(art+"Cash bundle mesh.asset");if(!mesh){mesh=UnityEngine.Object.Instantiate(original);var vertices=mesh.vertices;var normals=mesh.normals;var center=mesh.bounds.center;float scale=.18f/mesh.bounds.size.y;for(int i=0;i<vertices.Length;i++){var p=vertices[i]-center;vertices[i]=new Vector3(p.x,-p.z,p.y)*scale;var n=normals[i];normals[i]=new Vector3(n.x,-n.z,n.y);}mesh.vertices=vertices;mesh.normals=normals;mesh.RecalculateBounds();mesh.name="Supplied cash bundle";AssetDatabase.CreateAsset(mesh,art+"Cash bundle mesh.asset");}var mat=AssetDatabase.LoadAssetAtPath<Material>(art+"Cash shared atlas.mat");if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,art+"Cash shared atlas.mat");}mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(art+"Cash atlas.png");mat.color=Color.white;mat.SetFloat("_Smoothness",.1f);mat.SetFloat("_Cull",0);EditorUtility.SetDirty(mat);
   var go=new GameObject("Cash payment");go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=mat;var box=go.AddComponent<BoxCollider>();box.size=new Vector3(.20f,.10f,.24f);box.isTrigger=true;var item=go.AddComponent<HotelItem>();item.kind="cashOffer";item.displayName="Customer cash payment";item.dimensions=mesh.bounds.size;go.AddComponent<HotelCash>();PrefabUtility.SaveAsPrefabAsset(go,output+"Cash payment.prefab");UnityEngine.Object.DestroyImmediate(go);AssetDatabase.SaveAssets();AssetDatabase.Refresh();Debug.Log("Built physical cash from the supplied GLB.");}
 }
}
